        "try{if(cacheKey&&typeof cache!=='undefined'&&cache&&typeof cache.putMemory==='function')cache.putMemory(cacheKey,encoded);}catch(ignoreCache){}" +
        "var button=document.getElementById('complete');button.style.display='block';button.onclick=requestClose;" +
        "setStatus('微信已确认，正在返回并写入登录参数...',false);setTimeout(requestClose,300);setTimeout(function(){if(document.visibilityState!=='hidden')requestClose();},1300);}" +
        "function parse(raw){try{return JSON.parse(String(raw||''));}catch(e){throw new Error('扫码状态返回无效');}}" +
        "async function poll(){if(stopped)return;if(Date.now()-started>280000){setStatus('二维码等待超时，请返回后重新生成',true);return;}" +
        "var url='https://long.open.weixin.qq.com/connect/l/qrconnect?f=json&uuid='+encodeURIComponent(uuid)+(last?'&last='+last:'');" +
        "try{var response=await fetch(url,{method:'GET',cache:'no-store',credentials:'omit'});if(!response.ok)throw new Error('HTTP '+response.status);var raw=await response.text();failures=0;" +
        "var data=parse(raw),code=Number(data.wx_errcode);if(code===405&&data.wx_code){finish(data.wx_code);return;}" +
        "if(code===404){last='404';setStatus('已扫码，请在微信中确认登录',false);setTimeout(poll,80);return;}" +
        "if(code===408){last='408';setStatus('正在等待扫码...',false);setTimeout(poll,80);return;}" +
        "if(code===402||code===403){setStatus('二维码已失效或登录被拒绝，请返回重试',true);return;}" +
        "setStatus('扫码状态 '+code+'，正在重试...',true);setTimeout(poll,1200);}" +
        "catch(e){failures++;setStatus('扫码状态请求失败，正在重试（'+failures+'）：'+String(e&&e.message||e),true);setTimeout(poll,1500);}}setTimeout(poll,300);})();</script></body></html>";
}
function wrInputToggle(input, src, name, fallback) {
    var value = wrInputValue(input, name) || wrValue(src, name);
