}
function wrUpdateCommentSettings(j, src, input, closeAll) {
    var names = ["段评开关", "章评开关", "书评开关", "作者评论开关"];
    var saved = {};
    var current = null;
    try { current = src.getLoginInfoMap(); } catch (ignoreLoginInfo) {}
    if (current) {
        try {
            var iterator = current.entrySet().iterator();
            while (iterator.hasNext()) {
                var entry = iterator.next();
                saved[String(entry.getKey())] = String(entry.getValue());
            }
        } catch (ignoreJavaMap) {
            try {
                current.forEach(function(value, key) { saved[String(key)] = String(value); });
            } catch (ignoreJsMap) {}
        }
    }
    var updates = new Packages.java.util.HashMap();
    for (var i = 0; i < names.length; i++) {
        var value = closeAll ? "🔳" : wrInputToggle(input, src, names[i], "🔳");
        saved[names[i]] = value;
        updates.put(names[i], value);
    }
    wrApplyCommentPreferences(input, src, saved);
    src.putLoginInfo(JSON.stringify(saved));
    j.upLoginData(updates);
    try { j.refreshContent(); } catch (ignoreRefresh) {}
    j.longToast(closeAll ? "全部评论已关闭，正文已刷新" : "评论设置已保存，正文已刷新");
    return closeAll ? "全部评论已关闭" : "评论设置已保存";
}
function wrSaveGuestLogin(j, src, input, state, userAgent, guest, captcha) {
