(function() {
    var xml = result;
    if (typeof xml !== 'string') return [];
    var list = [];
    var cpRegex = /<cp>([\s\S]*?)<\/cp>/g;
    var match;
    while ((match = cpRegex.exec(xml)) !== null) {
        list.push(match[1]);
    }
    return list;
})();

